structlogger = structlog.get_logger()


def configure_backend_tracing(endpoints_file: str) -> None:
    """Configure backend tracing from an ``endpoints.yml`` path."""
    tracer_provider = _get_tracer_provider(endpoints_file)
    if tracer_provider is None:
        return
    _apply_tracer_provider(tracer_provider)


def configure_backend_tracing_from_endpoint_config(
    tracing_config: EndpointConfig, *, source: str
) -> None:
    """Configure backend tracing from an already-parsed endpoint config.

    Args:
        tracing_config: OTLP or Jaeger tracing settings.
        source: Human-readable origin used in log messages (e.g. file path).
    """
    tracer_provider = _tracer_provider_from_endpoint_config(
        tracing_config, source=source
    )
    if tracer_provider is None:
        return
    _apply_tracer_provider(tracer_provider)


def configure_backend_tracing_for_project(
    project_root: Union[str, Path, None] = None,
    endpoints_file: Optional[str] = None,
    is_mantle: Optional[bool] = None,
) -> None:
    """Configure backend tracing from ``integrations.yml`` or ``endpoints.yml``.

    Mantle contexts read only the OTLP or Jaeger entry of ``tracing:`` in
    ``integrations.yml``; *endpoints_file* is never consulted for tracing.
    An invalid ``tracing:`` block is logged and leaves backend tracing off
    instead of aborting the command. CALM contexts only read endpoints.

    Args:
        project_root: Project directory used to locate ``integrations.yml``.
            Defaults to the current working directory.
        endpoints_file: Path to endpoints configuration, if any. Ignored for
            Mantle contexts.
        is_mantle: Whether the CLI context is Mantle, as resolved by the caller
            (see :func:`~rasa.shared.engine_version.is_mantle_cli_context`).
            ``None`` falls back to the on-disk project layout.
    """
    from rasa.shared.project_structure import has_mantle_project_layout

    root = Path(project_root) if project_root is not None else Path.cwd()
    if is_mantle is None:
        is_mantle = has_mantle_project_layout(root)
    if is_mantle:
        _configure_backend_tracing_from_integrations(root)
    elif endpoints_file is not None:
        configure_backend_tracing(endpoints_file)


def _configure_backend_tracing_from_integrations(project_root: Path) -> None:
    """Apply the OTLP or Jaeger entry of ``tracing:`` in ``integrations.yml``."""
    # Lazy import so CALM-only runs do not pull Mantle config modules.
    from rasa.mantle.config.tracing import load_integration_tracing
    from rasa.shared.project_structure import MANTLE_INTEGRATIONS_FILE

    integration_file = project_root / MANTLE_INTEGRATIONS_FILE
    try:
        settings = load_integration_tracing(project_root, tracer="backend")
    except RasaException as error:
        structlogger.error(
            "backend_tracing.integration_tracing_invalid",
            event_info=(
                f"Invalid 'tracing:' configuration in {integration_file}: "
                f"{error} Backend tracing will not be configured."
            ),
        )
        return

    if settings is None or settings.backend is None:
        return
    configure_backend_tracing_from_endpoint_config(
        EndpointConfig.from_dict(settings.backend.as_config_dict()),
        source=str(integration_file),
    )


def _apply_tracer_provider(tracer_provider: TracerProvider) -> None:
    """Register the provider globally and instrument Rasa classes."""
    _register_global_tracer_provider(tracer_provider)

    classes_to_instrument = _collect_classes_to_instrument()

    instrumentation.instrument(
        tracer_provider=tracer_provider,
        agent_class=Agent,
        # TODO(ENG-2866): also instrument MantleMessageProcessor once the Mantle
        # engine ships to production (its engine-specific methods differ).
        processor_class=CalmMessageProcessor,
        tracker_store_class=TrackerStore,
        graph_node_class=GraphNode,
        graph_trainer_class=GraphTrainer,
        llm_command_generator_class=LLMCommandGenerator,
        command_subclasses=classes_to_instrument["command_subclasses"],
        contextual_response_rephraser_class=classes_to_instrument[
            "contextual_response_rephraser_class"
        ],
        policy_subclasses=classes_to_instrument["policy_subclasses"],
        vector_store_subclasses=classes_to_instrument["vector_store_subclasses"],
        nlu_command_adapter_class=NLUCommandAdapter,
        endpoint_config_class=EndpointConfig,
        grpc_custom_action_executor_class=GRPCCustomActionExecutor,
        single_step_llm_command_generator_class=SingleStepLLMCommandGenerator,
        compact_llm_command_generator_class=CompactLLMCommandGenerator,
        search_ready_llm_command_generator_class=SearchReadyLLMCommandGenerator,
        multi_step_llm_command_generator_class=MultiStepLLMCommandGenerator,
        custom_action_executor_subclasses=classes_to_instrument[
            "custom_action_executor_subclasses"
        ],
        flow_retrieval_class=FlowRetrieval,
        subagent_classes=classes_to_instrument["agent_classes"],
    )


def _register_global_tracer_provider(tracer_provider: TracerProvider) -> None:
    """Register a global SDK provider unless one is already available.

    Reusing an existing provider preserves its configured span processors.
    Otherwise, ``tracer_provider`` becomes the provider used by spans that
    resolve their tracer at runtime.
    """
    if isinstance(trace.get_tracer_provider(), TracerProvider):
        structlogger.debug(
            "backend_tracing.global_tracer_provider.reused",
            event_info=(
                "A global SDK tracer provider is already installed; "
                "explicit spans will record through it."
            ),
        )
        return
    trace.set_tracer_provider(tracer_provider)


def _collect_classes_to_instrument() -> Dict[str, Any]:
    """Collect all classes that need to be instrumented for tracing."""
    # Imported only so its module body loads the built-in policies. Do not read
    # DEFAULT_COMPONENTS or an availability flag: that imports TensorFlow, and
    # tracing is configured before the tracker store connects. TensorFlow's
    # OpenSSL then breaks libpq's TLS handshake (ENG-3472). Policies loaded later,
    # like TEDPolicy, are traced via the `Policy._prediction` wrapper instead.
    import rasa.engine.recipes.default_components  # noqa: F401
    from rasa.core.information_retrieval.information_retrieval import (
        InformationRetrieval,
    )
    from rasa.core.nlg.contextual_response_rephraser import ContextualResponseRephraser
    from rasa.core.policies.policy import Policy
    from rasa.shared.utils.common import all_subclasses

    command_subclasses = [subclass for subclass in Command.__subclasses__()] + [
        subclass for subclass in FreeFormAnswerCommand.__subclasses__()
    ]

    policy_subclasses = [
        policy_class
        for policy_class in dict.fromkeys(all_subclasses(Policy))
        if policy_class.__module__.startswith("rasa.")
    ]

    vector_store_subclasses = [
        vector_store_class
        for vector_store_class in InformationRetrieval.__subclasses__()
    ]

    custom_action_executor_subclasses = []
    for custom_action_executor_class in CustomActionExecutor.__subclasses__():
        if custom_action_executor_class != RetryCustomActionExecutor:
            custom_action_executor_subclasses.append(custom_action_executor_class)

    agent_classes = [MCPOpenAgent, MCPTaskAgent, A2AAgent]

    return {
        "command_subclasses": command_subclasses,
        "policy_subclasses": policy_subclasses,
        "vector_store_subclasses": vector_store_subclasses,
        "custom_action_executor_subclasses": custom_action_executor_subclasses,
        "agent_classes": agent_classes,
        "contextual_response_rephraser_class": ContextualResponseRephraser,
    }


def _get_tracer_provider(endpoints_file: Text) -> Optional[TracerProvider]:
    """Build a tracer provider from a backend tracing block in endpoints.yml."""
    tracing_config = read_backend_tracing_configuration(
        endpoints_file, ENDPOINTS_TRACING_KEY
    )

    if not tracing_config:
        structlogger.info(
            "endpoint.read.no_backend_tracing_config",
            filename=os.path.abspath(endpoints_file),
            event_info=(
                f"No backend tracing configuration found in {endpoints_file}. "
                f"Supported backend tracing types are 'jaeger' and 'otlp'. "
                f"Backend tracing will not be configured."
            ),
        )
        return None

    return _tracer_provider_from_endpoint_config(
        tracing_config, source=str(endpoints_file)
    )


def _tracer_provider_from_endpoint_config(
    tracing_config: EndpointConfig, *, source: str
) -> Optional[TracerProvider]:
    """Build a tracer provider from a parsed OTLP or Jaeger config."""
    if tracing_config.type == "jaeger":
        return JaegerTracerConfigurer.configure_from_endpoint_config(tracing_config)
    if tracing_config.type == ENDPOINTS_OTLP_BACKEND_TYPE:
        return OTLPCollectorConfigurer.configure_from_endpoint_config(tracing_config)

    structlogger.warning(
        "endpoint.read.unknown_tracing_type",
        filename=os.path.abspath(source) if os.path.exists(source) else source,
        event_info=(
            f"Unknown tracing type {tracing_config.type} read from "
            f"{source}, ignoring."
        ),
    )
    return None


class TracerConfigurer(abc.ABC):
    """Abstract superclass for tracing configuration.

    `TracerConfigurer` is the abstract superclass from which all configurers
    for different supported backends should inherit.
    """

    @classmethod
    @abc.abstractmethod
    def configure_from_endpoint_config(cls, config: EndpointConfig) -> TracerProvider:
        """Configure tracing.

        This abstract method should be implemented by all concrete `TracerConfigurer`s.
        It shall read the configuration from the supplied argument, configure all
        necessary infrastructure for tracing, and return the `TracerProvider` to be
        used for tracing purposes.

        :param config: The configuration to be read for configuring tracing.
        :return: The configured `TracerProvider`.
        """


class JaegerTracerConfigurer(TracerConfigurer):
    """The `TracerConfigurer` for a Jaeger backend.

    This class maintains backward compatibility with the old Jaeger configuration
    format while internally using OTLP to avoid protobuf compatibility issues.
    """

    @classmethod
    def configure_from_endpoint_config(cls, config: EndpointConfig) -> TracerProvider:
        """Configure tracing for Jaeger using OTLP under the hood.

        This maintains backward compatibility with the old Jaeger configuration format
        while using OTLP internally to avoid protobuf compatibility issues.

        :param config: The configuration to be read for configuring tracing.
        :return: The configured `TracerProvider`.
        """
        jaeger_config = cls._extract_config(config)
        otlp_endpoint = cls._build_otlp_endpoint(jaeger_config)
        credentials = _get_credentials(config, jaeger_config["insecure"])
        otlp_exporter = cls._create_otlp_exporter(
            jaeger_config, otlp_endpoint, credentials
        )
        provider = cls._create_tracer_provider(config)

        if jaeger_config["insecure"] and cls._build_headers(jaeger_config):
            cls._warn_plaintext_credentials(jaeger_config, otlp_endpoint)

        structlogger.info(
            "endpoint.read.jaeger_config_configured",
            event_info=(
                f"Registered {config.type} endpoint for tracing using OTLP. "
                f"Traces will be exported to {otlp_endpoint}."
            ),
        )
        provider.add_span_processor(_span_processor(config, otlp_exporter))

        return provider

    @classmethod
    def _extract_config(cls, config: EndpointConfig) -> Dict[str, Any]:
        """Extract Jaeger configuration parameters."""
        insecure = config.kwargs.get(ENDPOINTS_INSECURE_KEY)
        return {
            "agent_host_name": config.kwargs.get("host", "localhost"),
            # Traces go to the collector's OTLP gRPC port, not the legacy
            # Jaeger agent's UDP port 6831.
            "agent_port": config.kwargs.get("port", 4317),
            "username": config.kwargs.get("username"),
            "password": config.kwargs.get("password"),
            # Plaintext unless explicitly disabled, for backward compatibility.
            "insecure": insecure is not False,
            # Credentials go over plaintext only on an explicit opt-in.
            "allow_plaintext_credentials": insecure is True,
        }

    @classmethod
    def _build_otlp_endpoint(cls, jaeger_config: Dict[str, Any]) -> str:
        """Build OTLP endpoint URL from Jaeger configuration."""
        host = jaeger_config["agent_host_name"]
        port = jaeger_config.get("agent_port", 4317)
        scheme = "http" if jaeger_config.get("insecure", True) else "https"
        return f"{scheme}://{host}:{port}"

    @classmethod
    def _create_otlp_exporter(
        cls,
        jaeger_config: Dict[str, Any],
        otlp_endpoint: str,
        credentials: Optional[grpc.ChannelCredentials] = None,
    ) -> OTLPSpanExporter:
        """Create OTLP exporter with Jaeger-compatible configuration."""
        headers = None
        if cls._may_send_credentials(jaeger_config):
            headers = cls._build_headers(jaeger_config)
        return OTLPSpanExporter(
            endpoint=otlp_endpoint,
            insecure=jaeger_config.get("insecure", True),
            credentials=credentials,
            headers=headers,
        )

    @classmethod
    def _create_tracer_provider(cls, config: EndpointConfig) -> TracerProvider:
        """Create TracerProvider with service name from configuration."""
        service_name = config.kwargs.get(
            ENDPOINTS_TRACING_SERVICE_NAME_KEY, TRACING_SERVICE_NAME
        )
        return TracerProvider(resource=Resource.create({SERVICE_NAME: service_name}))

    @classmethod
    def _build_headers(cls, jaeger_config: Dict[str, Any]) -> Optional[Dict[str, str]]:
        """Build OTLP headers from Jaeger authentication config."""
        username = jaeger_config.get("username")
        password = jaeger_config.get("password")

        if not username or not password:
            return None

        credentials = base64.b64encode(f"{username}:{password}".encode()).decode()
        # gRPC rejects metadata keys that are not lowercase.
        return {"authorization": f"Basic {credentials}"}

    @classmethod
    def _may_send_credentials(cls, jaeger_config: Dict[str, Any]) -> bool:
        """Whether credentials may be attached to the export channel."""
        return not jaeger_config.get("insecure", True) or jaeger_config.get(
            "allow_plaintext_credentials", False
        )

    @classmethod
    def _warn_plaintext_credentials(
        cls, jaeger_config: Dict[str, Any], otlp_endpoint: str
    ) -> None:
        """Warn that credentials are sent unencrypted or were withheld."""
        tls_hint = (
            f"Set '{ENDPOINTS_INSECURE_KEY}: false' (optionally with "
            f"'{ENDPOINTS_ROOT_CERTIFICATES_KEY}') to export over TLS."
        )
        if cls._may_send_credentials(jaeger_config):
            structlogger.warning(
                "endpoint.read.jaeger_credentials_sent_in_plaintext",
                event_info=(
                    f"Jaeger credentials will be sent unencrypted to "
                    f"{otlp_endpoint}. {tls_hint}"
                ),
            )
            return
        structlogger.warning(
            "endpoint.read.jaeger_credentials_not_sent",
            event_info=(
                f"Jaeger credentials are not sent to {otlp_endpoint} because the "
                f"connection is unencrypted. {tls_hint} To send them unencrypted, "
                f"set '{ENDPOINTS_INSECURE_KEY}: true'."
            ),
        )


class OTLPCollectorConfigurer(TracerConfigurer):
    """The `TracerConfigurer` for an OTLP collector backend."""

    @classmethod
    def configure_from_endpoint_config(cls, config: EndpointConfig) -> TracerProvider:
        """Configure tracing for OTLP Collector.

        This will read the OTLP collector-specific configuration from the
        `EndpointConfig` and create a corresponding `TracerProvider` that exports to
        the given OTLP collector.
        Currently, this only supports insecure connections via gRPC.

        :param config: The configuration to be read for configuring tracing.
        :return: The configured `TracerProvider`.
        """
        provider = cls._create_tracer_provider(config)
        insecure = config.kwargs.get(ENDPOINTS_INSECURE_KEY)
        credentials = _get_credentials(config, insecure)
        otlp_exporter = cls._create_otlp_exporter(config, insecure, credentials)

        structlogger.info(
            "endpoint.read.otlp_collector_config_configured",
            event_info=(
                f"Registered {config.type} endpoint for tracing. "
                f"Traces will be exported to {config.kwargs[ENDPOINTS_ENDPOINT_KEY]}"
            ),
        )
        provider.add_span_processor(BatchSpanProcessor(otlp_exporter))

        return provider

    @classmethod
    def _create_tracer_provider(cls, config: EndpointConfig) -> TracerProvider:
        """Create TracerProvider with service name from configuration."""
        service_name = config.kwargs.get(
            ENDPOINTS_TRACING_SERVICE_NAME_KEY, TRACING_SERVICE_NAME
        )
        return TracerProvider(resource=Resource.create({SERVICE_NAME: service_name}))

    @classmethod
    def _create_otlp_exporter(
        cls,
        config: EndpointConfig,
        insecure: Optional[bool],
        credentials: Optional[grpc.ChannelCredentials],
    ) -> OTLPSpanExporter:
        """Create OTLP exporter from configuration."""
        return OTLPSpanExporter(
            endpoint=config.kwargs[ENDPOINTS_ENDPOINT_KEY],
            insecure=insecure,
            credentials=credentials,
        )


def _span_processor(
    config: EndpointConfig, exporter: OTLPSpanExporter
) -> Union[BatchSpanProcessor, SimpleSpanProcessor]:
    """Return a synchronous processor only when ``sync_export`` is true.

    Null and false keep batched export, matching Jaeger configs that set
    ``sync_export: ~``.
    """
    if config.kwargs.get("sync_export") is True:
        return SimpleSpanProcessor(exporter)
    return BatchSpanProcessor(exporter)


def _get_credentials(
    config: EndpointConfig, insecure: Optional[bool]
) -> Optional[grpc.ChannelCredentials]:
    """Get gRPC credentials from configuration."""
    credentials = None
    if not insecure and ENDPOINTS_ROOT_CERTIFICATES_KEY in config.kwargs:
        with open(config.kwargs.get(ENDPOINTS_ROOT_CERTIFICATES_KEY), "rb") as f:
            root_cert = f.read()
        credentials = grpc.ssl_channel_credentials(root_certificates=root_cert)
    return credentials
